// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Recorder rec;

    function setUp() public { c = new MultiplicatorX4(); rec = new Recorder(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < 1e30);

        vm.deal(address(this), amount);
        vm.prank(address(this)); // setUp deployer is the Owner
        c.Command{value: amount}(address(rec), "");

        // General rule: the recipient records exactly the amount sent (and C retains nothing).
        assertTrue(rec.recorded() == amount && address(c).balance == 0);
    }
}

contract Recorder {
    uint256 public recorded;
    receive() external payable { recorded += msg.value; }
}
